#include <stdlib.h>
#include <string.h>
int process_with_progress(const char* input, void (*progress)(size_t, size_t, void*), void* ctx, char** out_json) {
  size_t total = strlen(input);
  size_t done = 0;
  while (done < total) {
    size_t step = total - done >= 1024 ? 1024 : total - done;
    done += step;
    if (progress) progress(done, total, ctx);
